/**
 * Contracts for the connection and explorer endpoints (`/api/connections/...`).
 *
 * SECURITY: nothing here carries a password. A connection is identified by an
 * opaque `id` generated by the server; the browser never receives credentials.
 */
import { z } from "zod";
import {
  columnInfoSchema,
  constraintInfoSchema,
  indexInfoSchema,
  indexUsageReportSchema,
  tableStatisticsSchema,
  relationshipInfoSchema,
  rowPageSchema,
  schemaInfoSchema,
  searchHitSchema,
  tableDetailsEntrySchema,
  tableInfoSchema,
} from "./metadata.js";
import { profileIdSchema } from "./ids.js";
import { MAX_ROW_FILTERS, rowFilterSchema } from "./row-filters.js";
import { postgresConnectionSummarySchema } from "./postgres-connection.js";

/** The server's connection identifiers: unguessable URL-safe tokens. */
export const connectionIdSchema = z.string().regex(/^[A-Za-z0-9_-]{16,64}$/);

/** A schema or table name from a URL or query string. Bounded; the database does the real matching. */
export const identifierSchema = z.string().min(1).max(255);

/** Query string of the endpoints that need a schema (`?schema=public`). */
export const schemaQuerySchema = z.object({ schema: identifierSchema });

/** One table named in a request. Strict: unknown keys are rejected. */
export const tableRefSchema = z.strictObject({ schema: identifierSchema, name: identifierSchema });

/** The most tables one bulk request may ask for. Bounds the work and the size of the answer. */
export const MAX_TABLES_PER_DETAILS_REQUEST = 500;

/** Body of `POST /api/connections/:id/table-details`. */
export const tablesDetailsRequestSchema = z.strictObject({
  tables: z.array(tableRefSchema).min(1).max(MAX_TABLES_PER_DETAILS_REQUEST),
});

/** A saved connection as the browser sees it: everything except the password. */
export const connectionSummarySchema = postgresConnectionSummarySchema.extend({
  id: connectionIdSchema,
  provider: z.literal("postgresql"),
  /** The saved profile this connection belongs to, or null when it was not saved. */
  profileId: profileIdSchema.nullable(),
});
export type ConnectionSummary = z.infer<typeof connectionSummarySchema>;

// --- Responses -------------------------------------------------------------

/** Generic "it worked" answer (test connection, disconnect). */
export const okResponseSchema = z.object({ ok: z.literal(true) });

export const connectionResponseSchema = z.object({ connection: connectionSummarySchema });
export type ConnectionResponse = z.infer<typeof connectionResponseSchema>;

export const listConnectionsResponseSchema = z.object({
  connections: z.array(connectionSummarySchema),
});
export type ListConnectionsResponse = z.infer<typeof listConnectionsResponseSchema>;

export const schemasResponseSchema = z.object({ schemas: z.array(schemaInfoSchema) });
export const tablesResponseSchema = z.object({ tables: z.array(tableInfoSchema) });

/** Everything the table detail panel shows, fetched in one round trip. */
export const tableDetailsResponseSchema = z.object({
  columns: z.array(columnInfoSchema),
  constraints: z.array(constraintInfoSchema),
  indexes: z.array(indexInfoSchema),
});

/** Answer to a bulk request: one entry per requested table, in request order. */
export const tablesDetailsResponseSchema = z.object({ tables: z.array(tableDetailsEntrySchema) });

export const relationshipsResponseSchema = z.object({
  relationships: z.array(relationshipInfoSchema),
});

/** Query string of `GET /api/connections/:id/search`. `limit` arrives as text in a URL, so it is converted here. */
export const MAX_SEARCH_RESULTS = 50;
export const searchQuerySchema = z.object({
  q: z.string().trim().min(1).max(100),
  limit: z.coerce.number().int().min(1).max(MAX_SEARCH_RESULTS).default(20),
});

export const searchResponseSchema = z.object({ hits: z.array(searchHitSchema) });

/** `GET /api/connections/:id/index-usage`: usage counters of the indexes (statistics, not rows). */
export const indexUsageResponseSchema = z.object({ usage: indexUsageReportSchema });

/**
 * `GET /api/connections/:id/tables/:table/statistics?schema=`: what the server's statistics say about one table (the
 * share of NULLs, distinct values, widths, sizes, last vacuum and analyze), null for a view or a foreign table. No row
 * and no value is read.
 */
export const tableStatisticsResponseSchema = z.object({
  statistics: tableStatisticsSchema.nullable(),
});

// --- Table data (rows) ------------------------------------------------------

/** Sort by one column: the table's key breaks ties. Strict, like the request around it. */
export const rowSortSchema = z.strictObject({
  column: identifierSchema,
  direction: z.enum(["asc", "desc"]),
});

/**
 * `POST /api/connections/:id/rows`: one page of a table's rows. A POST with a JSON
 * body, so table names, paging positions and the values of conditions never appear
 * in a URL, the history or a log. Strict: any other key (a `where`, an `orderBy`, a
 * `sql`) is refused. A sort and conditions are structured, never text that becomes SQL.
 */
export const rowsRequestSchema = z.strictObject({
  schema: identifierSchema,
  table: identifierSchema,
  /** 1 to 200 (the server's page-size limit). */
  pageSize: z.number().int().min(1).max(200).default(50),
  /** The `nextCursor` of the previous page; opaque and untrusted. */
  cursor: z.string().min(1).max(4096).nullable().default(null),
  /** Columns that look sensitive are not read unless named here. */
  revealColumns: z.array(identifierSchema).max(100).default([]),
  /** Sort by one column; null for the key order. */
  sort: rowSortSchema.nullable().default(null),
  /** Up to 10 conditions, all required except those that share a group (any one of them is enough). */
  filters: z.array(rowFilterSchema).max(MAX_ROW_FILTERS).default([]),
});
/** What a client may send (defaults are optional). */
export type RowsRequest = z.input<typeof rowsRequestSchema>;
/** What the server works with, after validation (defaults applied). */
export type ParsedRowsRequest = z.output<typeof rowsRequestSchema>;

export const rowsResponseSchema = z.object({ page: rowPageSchema });

/**
 * `POST /api/connections/:id/rows/cell`: ONE `json` or `jsonb` value of ONE row, read whole (up to 1 MB),
 * for the JSON editor. The row is named by its key (one entry per key column), never by a condition.
 * Strict, like the request for a page; a value of the key is a value and is never logged or echoed.
 */
export const cellRequestSchema = z.strictObject({
  schema: identifierSchema,
  table: identifierSchema,
  column: identifierSchema,
  key: z
    .array(z.strictObject({ column: identifierSchema, value: z.string().max(4096) }))
    .min(1)
    .max(32),
  revealColumns: z.array(identifierSchema).max(100).default([]),
});
export type CellRequestBody = z.input<typeof cellRequestSchema>;
export type ParsedCellRequest = z.output<typeof cellRequestSchema>;

/** The largest body of a validation (it carries the values to be checked): what an import can carry. */
export const VALIDATE_MAX_BODY_BYTES = 32 * 1024 * 1024;

/**
 * `POST /api/connections/:id/rows/validate`: would the database accept these values? Answered without
 * writing a row (decision 157). `insert` checks up to 100,000 rows (an import); `update` checks one row, found by its key.
 * Strict, and bounded in every list. The values are values: never logged, saved or echoed.
 */
export const validateRequestSchema = z.strictObject({
  schema: identifierSchema,
  table: identifierSchema,
  mode: z.enum(["insert", "update"]),
  columns: z.array(identifierSchema).max(50),
  rows: z
    .array(z.array(z.string().max(100_000).nullable()).max(50))
    .min(1)
    .max(100_000),
  key: z
    .array(z.strictObject({ column: identifierSchema, value: z.string().max(4096) }))
    .min(1)
    .max(32)
    .optional(),
});
export type ValidateRequestBody = z.input<typeof validateRequestSchema>;
export type ParsedValidateRequest = z.output<typeof validateRequestSchema>;

const validationIssueSchema = z.object({
  rule: z.enum([
    "not_null",
    "check",
    "type",
    "unique_in_request",
    "unique_existing",
    "foreign_key",
    "no_effects",
    "rejected",
  ]),
  column: z.string().nullable(),
  constraint: z.string().nullable(),
  count: z.number().int(),
  rows: z.array(z.number().int()),
});
export const validationReportSchema = z.object({
  rows: z.number().int(),
  passed: z.number().int(),
  issues: z.array(validationIssueSchema),
  notChecked: z.array(
    z.enum([
      "triggers",
      "row_level_security",
      "other_unique_indexes",
      "foreign_key_unreadable",
      "stopped_early",
      "defaults_not_applied",
      "exclusion_constraints",
      "partition_bounds",
      "event_triggers",
      "hidden_columns",
    ]),
  ),
});
export const validateResponseSchema = z.object({ report: validationReportSchema });

/**
 * `POST /api/connections/:id/rows/preflight`: how many rows would make steps of a migration fail
 * (section 6.3 of the plan). Up to 50 checks, each a structure (names, never SQL), strict, bounded.
 */
const preflightColumns = z.array(identifierSchema).min(1).max(32);
export const preflightCheckSchema = z.discriminatedUnion("kind", [
  z.strictObject({
    kind: z.literal("nulls"),
    schema: identifierSchema,
    table: identifierSchema,
    column: identifierSchema,
  }),
  z.strictObject({
    kind: z.literal("duplicates"),
    schema: identifierSchema,
    table: identifierSchema,
    columns: preflightColumns,
  }),
  z.strictObject({
    kind: z.literal("orphans"),
    schema: identifierSchema,
    table: identifierSchema,
    columns: preflightColumns,
    refSchema: identifierSchema,
    refTable: identifierSchema,
    refColumns: preflightColumns,
  }),
  z.strictObject({ kind: z.literal("rows"), schema: identifierSchema, table: identifierSchema }),
]);
export const preflightRequestSchema = z.strictObject({
  checks: z.array(preflightCheckSchema).min(1).max(50),
});
export type PreflightRequestBody = z.input<typeof preflightRequestSchema>;
export type ParsedPreflightRequest = z.output<typeof preflightRequestSchema>;
export const preflightResponseSchema = z.object({
  results: z.array(
    z.object({
      status: z.enum(["ok", "fails", "missing", "too_slow", "hidden"]),
      count: z.number().int(),
    }),
  ),
});

/**
 * `POST /api/connections/:id/rows/export`: the rows of a table as a file, as filtered and sorted on screen
 * (section 8 of the plan; decision 158). The answer is the FILE, streamed, not JSON. Strict and bounded; a
 * condition is a structure, a hidden column is left out unless revealed.
 */
export const exportRequestSchema = z.strictObject({
  schema: identifierSchema,
  table: identifierSchema,
  revealColumns: z.array(identifierSchema).max(100).default([]),
  sort: rowSortSchema.nullable().default(null),
  filters: z.array(rowFilterSchema).max(MAX_ROW_FILTERS).default([]),
  format: z.enum(["csv", "tsv", "json", "ndjson", "sql"]),
  /** Only these rows, each by the table's whole key (the chosen rows of the grid): at most 500. */
  keys: z
    .array(
      z
        .array(z.strictObject({ column: identifierSchema, value: z.string().max(4096) }))
        .min(1)
        .max(32),
    )
    .min(1)
    .max(500)
    .optional(),
  /** For CSV: a comma or a semicolon (a tab is TSV). */
  delimiter: z.enum([",", ";"]).default(","),
  header: z.boolean().default(true),
  /** What NULL is written as in CSV and TSV; empty by default (an empty string stays empty too). */
  nullText: z.string().max(50).default(""),
  /** Notes about the file even when it was not cut. */
  meta: z.boolean().default(false),
});
export type ExportRequestBody = z.input<typeof exportRequestSchema>;
export type ParsedExportRequest = z.output<typeof exportRequestSchema>;

/**
 * The largest body of an export request: 500 chosen rows with a composite key of two uuids are about 66 KB, and the
 * default limit of a body (64 KB) refused them (the review of 1.10.0). The keys of one request hold at most
 * `EXPORT_MAX_KEY_CHARS` characters of values altogether.
 */
export const EXPORT_MAX_BODY_BYTES = 4 * 1024 * 1024;
export const EXPORT_MAX_KEY_CHARS = 1_000_000;

export const cellResponseSchema = z.object({
  cell: z.object({ value: z.string().nullable(), tooLarge: z.boolean() }),
});

/** `PUT /api/connections/:id/data-access`: switch viewing table data on or off for this connection. */
export const dataAccessRequestSchema = z.strictObject({ enabled: z.boolean() });
export type DataAccessRequest = z.infer<typeof dataAccessRequestSchema>;
